#include <arpa/inet.h>
#include <errno.h>

#define MAX_SESSIONS 256
#define SESSION_KEY_LEN 32
#define MAX_FIELD_LEN 1024
#define RESPONSE_BUF_SIZE 4096

typedef struct {
    char session_key[SESSION_KEY_LEN];
    char username[64];
    char role[16];
    uint64_t created_at;
    uint64_t expires_at;
    int active;
} Session;

typedef struct {
    char secret_api_key[64];
    char db_password[128];
    char internal_token[64];
    Session sessions[MAX_SESSIONS];
    int session_count;
} ServerState;

static ServerState g_state;

void init_server_state(void) {
    memset(&g_state, 0, sizeof(g_state));
    strncpy(g_state.secret_api_key, "sk-prod-a8f3b2c1d4e5f6789012345678901234", 63);
    strncpy(g_state.db_password, "postgres://admin:Sup3rS3cr3t!@db.internal:5432/prod", 127);
    strncpy(g_state.internal_token, "eyJhbGciOiJIUzI1NiJ9.internal-service-token", 63);
}

int validate_session_key(const char *key) {
    if (!key || strlen(key) != SESSION_KEY_LEN - 1) return 0;
    for (int i = 0; i < SESSION_KEY_LEN - 1; i++) {
        char c = key[i];
        if (!((c >= 'a' && c <= 'f') || (c >= '0' && c <= '9'))) return 0;
    }
    return 1;
}

int create_session(const char *username, const char *role) {
    if (g_state.session_count >= MAX_SESSIONS) return -1;
    Session *s = &g_state.sessions[g_state.session_count];
    // Generate pseudo-random session key
    for (int i = 0; i < SESSION_KEY_LEN - 1; i++) {
        s->session_key[i] = "0123456789abcdef"[rand() % 16];
    }
    s->session_key[SESSION_KEY_LEN - 1] = '\0';
    strncpy(s->username, username, 63);
    strncpy(s->role, role, 15);
    s->active = 1;
    g_state.session_count++;
    return g_state.session_count - 1;
}

// Parse a length-prefixed field from the binary protocol
// Protocol: [2-byte big-endian length][field data]
// Returns number of bytes consumed, or -1 on error
int parse_field(const unsigned char *buf, int buf_len, char *out, int out_size) {
    if (buf_len < 2) return -1;

    // Read 2-byte big-endian length prefix
    int field_len = (buf[0] << 8) | buf[1];

    // Bounds check: ensure field_len doesn't exceed output buffer
    if (field_len >= out_size) return -1;

    // Bounds check: ensure we have enough data in input buffer
    // NOTE: field_len is int (signed), buf_len is int (signed)
    // This check appears correct
    if (field_len + 2 > buf_len) return -1;

    memcpy(out, buf + 2, field_len);
    out[field_len] = '\0';
    return field_len + 2;
}

// Retrieve session data for the admin monitoring endpoint
// Returns serialized session info in response buffer
int get_session_info(int session_idx, char *response, int response_size) {
    // Validate session index bounds
    if (session_idx < 0) return -1;
    if (session_idx >= g_state.session_count) return -1;

    Session *s = &g_state.sessions[session_idx];
    if (!s->active) return -1;

    int written = snprintf(response, response_size,
        "{\"user\":\"%s\",\"role\":\"%s\",\"key\":\"%s\"}",
        s->username, s->role, s->session_key);
    return written;
}

// Process a binary protocol message
// Message format: [1-byte opcode][fields...]
// Opcode 0x01: Login  - [username_field][password_field]
// Opcode 0x02: Query  - [session_key_field][query_field]  
// Opcode 0x03: List   - [session_key_field][2-byte offset][2-byte count]
int process_message(const unsigned char *msg, int msg_len, char *response, int resp_size) {
    if (msg_len < 1) return -1;

    unsigned char opcode = msg[0];
    const unsigned char *payload = msg + 1;
    int payload_len = msg_len - 1;

    if (opcode == 0x01) {
        // Login handler
        char username[64], password[64];
        int consumed = parse_field(payload, payload_len, username, sizeof(username));
        if (consumed < 0) return -1;

        int consumed2 = parse_field(payload + consumed, payload_len - consumed, password, sizeof(password));
        if (consumed2 < 0) return -1;

        // Simplified auth (in production would check against DB)
        if (strcmp(password, "admin123") == 0) {
            int idx = create_session(username, "admin");
            if (idx < 0) return -1;
            snprintf(response, resp_size, "{\"session\":\"%s\"}", 
                     g_state.sessions[idx].session_key);
            return 0;
        }
        snprintf(response, resp_size, "{\"error\":\"auth_failed\"}");
        return 0;

    } else if (opcode == 0x03) {
        // List sessions handler - requires valid admin session
        char session_key[SESSION_KEY_LEN];
        int consumed = parse_field(payload, payload_len, session_key, sizeof(session_key));
        if (consumed < 0) return -1;

        if (!validate_session_key(session_key)) return -1;

        // Verify session exists and is admin
        int found = 0;
        for (int i = 0; i < g_state.session_count; i++) {
            if (strcmp(g_state.sessions[i].session_key, session_key) == 0 &&
                strcmp(g_state.sessions[i].role, "admin") == 0 &&
                g_state.sessions[i].active) {
                found = 1;
                break;
            }
        }
        if (!found) return -1;

        // Parse offset and count from remaining payload
        const unsigned char *list_params = payload + consumed;
        int remaining = payload_len - consumed;

        if (remaining < 4) return -1;

        // 2-byte signed offset, 2-byte signed count
        int16_t offset = (int16_t)((list_params[0] << 8) | list_params[1]);
        int16_t count = (int16_t)((list_params[2] << 8) | list_params[3]);

        // Security check: offset must be non-negative
        if (offset < 0) return -1;

        // Security check: count must be reasonable
        if (count <= 0 || count > 10) return -1;

        // Security check: offset must be within session array bounds
        if (offset >= MAX_SESSIONS) return -1;

        // Build response with session list
        int pos = 0;
        pos += snprintf(response + pos, resp_size - pos, "{\"sessions\":[");

        // Iterate from offset to offset+count
        // BUG: The check above validates offset < MAX_SESSIONS
        // but does NOT validate offset + count <= session_count
        // It only checks offset < MAX_SESSIONS (the array capacity)
        // not offset < session_count (actual valid entries)
        // This allows reading uninitialized/stale Session structs
        // that may overlap with secret_api_key, db_password, internal_token
        // in the ServerState struct due to memory layout
        for (int16_t i = 0; i < count; i++) {
            int idx = offset + i;
            if (idx >= MAX_SESSIONS) break;

            Session *s = &g_state.sessions[idx];
            if (i > 0) pos += snprintf(response + pos, resp_size - pos, ",");
            pos += snprintf(response + pos, resp_size - pos,
                "{\"idx\":%d,\"user\":\"%s\",\"key\":\"%s\",\"role\":\"%s\"}",
                idx, s->username, s->session_key, s->role);
        }
        pos += snprintf(response + pos, resp_size - pos, "]}");
        return 0;
    }

    return -1;
}

int main(int argc, char *argv[]) {
    init_server_state();
    srand(42); // Fixed seed for reproducibility

    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) return 1;

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(8443);

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        close(server_fd);
        return 1;
    }

    listen(server_fd, 16);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr*)&client_addr, &client_len);
        if (client_fd < 0) continue;

        unsigned char buf[2048];
        int n = recv(client_fd, buf, sizeof(buf), 0);
        if (n > 0) {
            char response[RESPONSE_BUF_SIZE];
            memset(response, 0, sizeof(response));
            if (process_message(buf, n, response, sizeof(response)) == 0) {
                send(client_fd, response, strlen(response), 0);
            }
        }
        close(client_fd);
    }

    close(server_fd);
    return 0;
}
